    ctx.fillStyle = '#3a3542';
    const G = makeWorld(data.brain);
    G.blocks.forEach(b => {
      const [c, r] = b.split(',').map(Number);
      ctx.fillRect(c * CELL, r * CELL, CELL, CELL);
    });
