    const drawUnit = (unit, color) => {
      const x = unit.c * CELL + CELL / 2;
      const y = unit.r * CELL + CELL / 2;
      ctx.beginPath(); ctx.arc(x, y, CELL * 0.35, 0, 2 * Math.PI);
      if (unit.alive === false) {
        ctx.strokeStyle = '#e8e2d0'; ctx.lineWidth = 2; ctx.stroke();
      } else {
        ctx.fillStyle = color; ctx.fill();
        // HP bar
        const barW = CELL * 0.7;
        const barH = 2;
        const barX = x - barW / 2;
        const barY = y + CELL * 0.35 + 2;
        ctx.fillStyle = '#3a3542';
        ctx.fillRect(barX, barY, barW, barH);
        const ratio = unit.pvMax > 0 ? unit.pv / unit.pvMax : 0;
        ctx.fillStyle = '#7fb069';
        ctx.fillRect(barX, barY, barW * ratio, barH);
      }
    };
    data.finalUnits.forEach(unit => {
      const color = unit.side === 'a' ? '#d9a441' : '#b5443c';
      drawUnit(unit, color);
    });
    // move polylines
    ctx.strokeStyle = '#e8e2d0';
    ctx.lineWidth = 2;
    data.turns.forEach(turn => {
      turn.actions.forEach(act => {
        if (act.type === 'move' && act.path && act.path.length > 0) {
          const points = [act.from, ...act.path];
          ctx.beginPath();
          ctx.moveTo(points[0].c * CELL + CELL / 2, points[0].r * CELL + CELL / 2);
          for (let i = 1; i < points.length; i++) {
            ctx.lineTo(points[i].c * CELL + CELL / 2, points[i].r * CELL + CELL / 2);
          }
          ctx.stroke();
        }
      });
    });
    // boss START position: small hollow red circle
    const sx = data.bossStart.c * CELL + CELL / 2;
    const sy = data.bossStart.r * CELL + CELL / 2;
    ctx.beginPath(); ctx.arc(sx, sy, CELL * 0.2, 0, 2 * Math.PI);
    ctx.strokeStyle = '#b5443c'; ctx.lineWidth = 2; ctx.stroke();
    // cast targets
    ctx.strokeStyle = '#f08a4b';
    ctx.lineWidth = 2;
    data.turns.forEach(turn => {
      turn.actions.forEach(act => {
        if (act.type === 'cast' && act.target) {
          const x = act.target.c * CELL + CELL / 2;
          const y = act.target.r * CELL + CELL / 2;
          ctx.beginPath(); ctx.moveTo(x - 5, y - 5); ctx.lineTo(x + 5, y + 5); ctx.moveTo(x + 5, y - 5); ctx.lineTo(x - 5, y + 5); ctx.stroke();
        }
      });
    });
  };
  const formatEffects = (eff) => {
    if (!eff || !eff.length) return '—';
    const parts = [];
    eff.forEach(e => {
      if (e.kind === 'damage') {
        let s = `${e.id} −${e.amount}`;
        if (e.killed) s += ' KO';
        if (e.absorbed > 0) s += ` (bouclier ${e.absorbed})`;
        parts.push(s);
      } else if (e.kind === 'heal') {
        parts.push(`${e.id} +${e.amount}`);
      } else if (e.kind === 'shield') {
        parts.push(`${e.id} bouclier +${e.amount}`);
      }
    });
    return parts.length ? parts.join(', ') : '—';
  };
